// Circuit Breaker Implementation
// ============================================================================

enum CircuitBreakerState {
  CLOSED = 'CLOSED',
  OPEN = 'OPEN',
  HALF_OPEN = 'HALF_OPEN'
}

interface CircuitBreakerConfig {
  failureThreshold: number;
  resetTimeout: number;
  halfOpenMaxAttempts: number;
}

class CircuitBreaker {
  private state: CircuitBreakerState = CircuitBreakerState.CLOSED;
  private failureCount: number = 0;
  private lastFailureTime: number = 0;
  private halfOpenAttempts: number = 0;
  private config: CircuitBreakerConfig;

  constructor(config: CircuitBreakerConfig) {
    this.config = config;
  }

  async execute<T>(operation: () => Promise<T>): Promise<T> {
    // Check if circuit should transition from OPEN to HALF_OPEN
    if (this.state === CircuitBreakerState.OPEN) {
      const timeSinceLastFailure = Date.now() - this.lastFailureTime;
      if (timeSinceLastFailure >= this.config.resetTimeout) {
        console.log('Circuit breaker transitioning to HALF_OPEN');
        this.state = CircuitBreakerState.HALF_OPEN;
        this.halfOpenAttempts = 0;
      } else {
        throw new Error(`Circuit breaker is OPEN. Retry after ${this.config.resetTimeout - timeSinceLastFailure}ms`);
      }
    }

    try {
      const result = await operation();

      // Success - handle state transitions
      if (this.state === CircuitBreakerState.HALF_OPEN) {
        this.halfOpenAttempts++;
        if (this.halfOpenAttempts >= this.config.halfOpenMaxAttempts) {
          console.log('Circuit breaker transitioning to CLOSED');
          this.state = CircuitBreakerState.CLOSED;
          this.failureCount = 0;
          this.halfOpenAttempts = 0;
        }
      } else if (this.state === CircuitBreakerState.CLOSED) {
        // Reset failure count on success
        this.failureCount = 0;
      }

      return result;

    } catch (error) {
      this.failureCount++;
      this.lastFailureTime = Date.now();

      // Check if we should open the circuit
      if (this.state === CircuitBreakerState.CLOSED && 
          this.failureCount >= this.config.failureThreshold) {
        console.log(`Circuit breaker OPENING after ${this.failureCount} failures`);
        this.state = CircuitBreakerState.OPEN;
      } else if (this.state === CircuitBreakerState.HALF_OPEN) {
        console.log('Circuit breaker returning to OPEN state');
        this.state = CircuitBreakerState.OPEN;
        this.halfOpenAttempts = 0;
      }

      throw error;
    }
  }

  isOpen(): boolean {
    return this.state === CircuitBreakerState.OPEN;
  }

  getState(): CircuitBreakerState {
    return this.state;
  }

  getMetrics() {
    return {
      state: this.state,
      failureCount: this.failureCount,
      lastFailureTime: this.lastFailureTime,
      halfOpenAttempts: this.halfOpenAttempts
    };
  }

  reset(): void {
    this.state = CircuitBreakerState.CLOSED;
    this.failureCount = 0;
    this.lastFailureTime = 0;
    this.halfOpenAttempts = 0;
  }
}

