// Step Handler Interface
// ============================================================================

export interface StepHandlerContext {
  context: ContextManager;
  config: any;
  stepId: string;
}

export interface StepHandlerResult {
  success: boolean;
  output?: any;
  error?: Error;
  metadata?: Record<string, any>;
}

// ============================================================================
// Step-Level Cache
// ============================================================================

interface CacheEntry {
  output: any;
  timestamp: number;
  hits: number;
}

class StepCache {
  private cache: Map<string, CacheEntry> = new Map();
  private readonly defaultTTL: number = 5 * 60 * 1000; // 5 minutes
  private readonly maxSize: number = 100;
  private cleanupInterval?: NodeJS.Timeout;

  constructor() {
    // Auto-cleanup expired entries every minute
    if (typeof setInterval !== 'undefined') {
      this.cleanupInterval = setInterval(() => {
        this.cleanExpired();
      }, 60 * 1000);
    }
  }

  /**
   * Generate cache key from step config and inputs
   */
  generateKey(stepType: string, config: any, inputs?: any): string {
    const data = JSON.stringify({ stepType, config, inputs });
    return crypto.createHash('sha256').update(data).digest('hex');
  }

  /**
   * Get cached result
   */
  get(key: string, ttl?: number): any | null {
    const entry = this.cache.get(key);

    if (!entry) {
      return null;
    }

    const effectiveTTL = ttl || this.defaultTTL;
    const now = Date.now();

    if (now - entry.timestamp > effectiveTTL) {
      this.cache.delete(key);
      return null;
    }

    // Update hit count
    entry.hits++;

    return entry.output;
  }

  /**
   * Set cache entry
   */
  set(key: string, output: any): void {
    // Evict oldest if at capacity
    if (this.cache.size >= this.maxSize) {
      const oldestKey = this.findOldest();
      if (oldestKey) {
        this.cache.delete(oldestKey);
      }
    }

    this.cache.set(key, {
      output,
      timestamp: Date.now(),
      hits: 0,
    });
  }

  /**
   * Clear specific entry
   */
  delete(key: string): void {
    this.cache.delete(key);
  }

  /**
   * Clear all cache
   */
  clear(): void {
    this.cache.clear();
  }

  /**
   * Clean expired entries
   */
  cleanExpired(): void {
    const now = Date.now();

    for (const [key, entry] of this.cache.entries()) {
      if (now - entry.timestamp > this.defaultTTL) {
        this.cache.delete(key);
      }
    }
  }

  /**
   * Find oldest entry for eviction
   */
  private findOldest(): string | null {
    let oldestKey: string | null = null;
    let oldestTime = Infinity;

    for (const [key, entry] of this.cache.entries()) {
      if (entry.timestamp < oldestTime) {
        oldestTime = entry.timestamp;
        oldestKey = key;
      }
    }

    return oldestKey;
  }

  /**
   * Get cache statistics
   */
  getStats() {
    let totalHits = 0;

    for (const entry of this.cache.values()) {
      totalHits += entry.hits;
    }

    return {
      size: this.cache.size,
      maxSize: this.maxSize,
      totalHits,
      avgHitsPerEntry: this.cache.size > 0 ? totalHits / this.cache.size : 0,
    };
  }

  /**
   * Cleanup on shutdown
   */
  destroy(): void {
    if (this.cleanupInterval) {
      clearInterval(this.cleanupInterval);
      this.cleanupInterval = undefined;
    }
    this.cache.clear();
  }
}

// Global cache instance
const stepCache = new StepCache();

// Cleanup on process exit
if (typeof process !== 'undefined') {
  process.on('SIGTERM', () => {
    stepCache.destroy();
  });
}

/**
 * Execute step with caching support
 */
async function executeWithCache<T>(
  cacheKey: string,
  cacheTTL: number | undefined,
  cacheEnabled: boolean,
  executor: () => Promise<T>
): Promise<T> {
  // Check if caching is enabled
  if (!cacheEnabled) {
    return executor();
  }

  // Try to get from cache
  const cached = stepCache.get(cacheKey, cacheTTL);
  if (cached !== null) {
    console.log(`Cache hit for key: ${cacheKey.substring(0, 16)}...`);
    return cached;
  }

  // Execute and cache result
  const result = await executor();
  stepCache.set(cacheKey, result);

  return result;
}

/**
 * Execute with timeout
 */
async function executeWithTimeout<T>(
  executor: () => Promise<T>,
  timeout: number,
  timeoutMessage: string
): Promise<T> {
  return Promise.race([
    executor(),
    new Promise<T>((_, reject) =>
      setTimeout(() => reject(new Error(timeoutMessage)), timeout)
    ),
  ]);
}"}

