  64       /\bdocument\b/i,
  65     ];
  66 
  67     for (const pattern of dangerousPatterns) {
  68       if (pattern.test(expression)) {
  69         errors.push(`Expression contains potentially dangerous pattern: ${pattern}`);
  70       }
  71     }
  72 
  73     // Check for valid syntax (basic check)
  74     try {
  75       this.parseExpression(expression);
  76     } catch (error) {
  77       errors.push(`Invalid syntax: ${error instanceof Error ? error.message : 'Unknown error'}`);
  78     }
