 197     // Split by && (higher precedence)
 198     const andParts = this.splitByOperator(expression, '&&');
 199     if (andParts.length > 1) {
 200       return {
 201         type: 'logical',
 202         operator: '&&',
 203         operands: andParts.map(part => this.parseExpression(part))
 204       };
 205     }
 206 
 207     return this.parseExpression(expression);
 208   }
