 210   /**
 211    * Split expression by operator, respecting parentheses
 212    */
 213   private splitByOperator(expression: string, operator: string): string[] {
 214     const parts: string[] = [];
 215     let current = '';
 216     let depth = 0;
 217     let i = 0;
 218 
 219     while (i < expression.length) {
 220       const char = expression[i];
 221       
 222       if (char === '(') {
 223         depth++;
 224         current += char;
 225       } else if (char === ')') {
 226         depth--;
 227         current += char;
 228       } else if (depth === 0 && expression.substring(i, i + operator.length) === operator) {
 229         parts.push(current.trim());
 230         current = '';
 231         i += operator.length - 1;
 232       } else {
 233         current += char;
 234       }
 235       
 236       i++;
 237     }
 238 
 239     if (current.trim()) {
 240       parts.push(current.trim());
 241     }
 242 
 243     return parts.length > 1 ? parts : [expression];
 244   }
 245 
 246   /**
 247    * Evaluate parsed expression
 248    */
 249   private evaluateParsedExpression(parsed: ParsedExpression, scope: Record<string, any>): boolean {
 250     switch (parsed.type) {
 251       case 'comparison':
 252         const left = this.resolveValue(parsed.left!, scope);
 253         const right = this.resolveValue(parsed.right!, scope);
 254         return this.compareValues(left, right, parsed.operator!);
 255 
 256       case 'logical':
 257         if (parsed.operator === '&&') {
 258           return parsed.operands!.every(op => this.evaluateParsedExpression(op, scope));
 259         } else if (parsed.operator === '||') {
 260           return parsed.operands!.some(op => this.evaluateParsedExpression(op, scope));
 261         }
 262         return false;
 263 
 264       case 'negation':
 265         return !this.evaluateParsedExpression(parsed.expression!, scope);
 266 
 267       case 'value':
 268         const value = this.resolveValue(parsed.value!, scope);
 269         return Boolean(value);
 270 
 271       default:
 272         return false;
 273     }
 274   }
 275 
 276   /**
 277    * Resolve a value from scope or parse as literal
 278    */
 279   private resolveValue(value: string, scope: Record<string, any>): any {
 280     value = value.trim();
 281 
 282     // Handle parentheses
 283     if (value.startsWith('(') && value.endsWith(')')) {
 284       value = value.substring(1, value.length - 1).trim();
 285     }
 286 
 287     // Boolean literals
 288     if (value === 'true') return true;
 289     if (value === 'false') return false;
 290 
 291     // Null/undefined
 292     if (value === 'null') return null;
 293     if (value === 'undefined') return undefined;
 294 
 295     // Number literals
 296     if (/^-?\d+(\.\d+)?$/.test(value)) {
 297       return parseFloat(value);
 298     }
 299 
 300     // String literals (single or double quotes)
 301     if ((value.startsWith('"') && value.endsWith('"')) ||
 302         (value.startsWith("'") && value.endsWith("'"))) {
 303       return value.substring(1, value.length - 1);
 304     }
 305 
 306     // Property access (e.g., input.userType or steps.step1.result)
 307     const parts = value.split('.');
 308     let current: any = scope;
 309     
 310     for (const part of parts) {
 311       if (current === null || current === undefined) {
 312         return undefined;
 313       }
 314       current = current[part];
 315     }
 316 
 317     return current;
 318   }
 319 
 320   /**
 321    * Compare two values using operator
 322    */
 323   private compareValues(left: any, right: any, operator: ComparisonOperator): boolean {
 324     switch (operator) {
 325       case '===': return left === right;
 326       case '!==': return left !== right;
 327       case '==': return left == right;
 328       case '!=': return left != right;
 329       case '<': return left < right;
 330       case '>': return left > right;
 331       case '<=': return left <= right;
 332       case '>=': return left >= right;
 333       default: return false;
 334     }
 335   }
 336 }
