 344   errors: string[];
 345 }
 346 
 347 type ComparisonOperator = '===' | '!==' | '==' | '!=' | '<' | '>' | '<=' | '>=';
 348 type LogicalOperator = '&&' | '||';
 349 
 350 type ParsedExpression = 
 351   | {
 352       type: 'comparison';
 353       left: string;
 354       operator: ComparisonOperator;
 355       right: string;
 356     }
 357   | {
 358       type: 'logical';
 359       operator: LogicalOperator;
 360       operands: ParsedExpression[];
 361     }
 362   | {
 363       type: 'negation';
 364       expression: ParsedExpression;
 365     }
 366   | {
 367       type: 'value';
 368       value: string;
 369     };
 370 
 371 // ============================================================================
 372 // Custom Errors
 373 // ============================================================================
 374 
 375 export class ConditionEvaluationError extends Error {
 376   constructor(
 377     message: string,
 378     public details?: any
 379   ) {
 380     super(message);
 381     this.name = 'ConditionEvaluationError';
 382   }
 383 }
